import{_ as s,l as n,o as a,c as h,v as r,p as o,x as i,d as l,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"编辑距离与 Hirschberg","description":"","frontmatter":{"title":"编辑距离与 Hirschberg","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/edit-distance-hirschberg.md","filePath":"cs/edit-distance-hirschberg.md","lastUpdated":1789023840000}'),p={name:"cs/edit-distance-hirschberg.md"};function m(b,e,_,g,u,f){const t=n("Mermaid");return a(),h("div",null,[e[1]||(e[1]=r('<h1 id="编辑距离与-hirschberg" tabindex="-1">编辑距离与 Hirschberg <a class="header-anchor" href="#编辑距离与-hirschberg" aria-label="Permalink to &quot;编辑距离与 Hirschberg&quot;">​</a></h1><div class="epigraph"><p>Levenshtein 距离是插、删、改的格图最短路；$O(nm)$ 时间，Hirschberg 用分治把空间降到线性并还原路径。</p><footer>—— 据 Levenshtein, 1966；Hirschberg, A Linear Space Algorithm for Computing Maximal Common Subsequences, 1975；CLRS 第 15 章整理</footer></div><p>上一课<a href="/cs/lis-lcs">LIS 与 LCS</a>给了 LCS 表。编辑距离：对角匹配代价 0，水平/垂直插删 1，对角替换 1（或另设）。缺口是同一格图的最短路，以及 Hirschberg：两边 DP 在中线相遇，递归还原，空间 \\(O(n+m)\\)。不重写 LCS 转移形状。后课序列比对与位并行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(dp[i][j]=\\min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+[a_i\\neq b_j])\\)。LCS 长度 \\(k\\) 时，若只插删，距离 \\(n+m-2k\\)。只要距离：滚动两行 \\(O(\\min(n,m))\\) 空间。要操作序列：朴素 \\(O(nm)\\) 空间存前驱。Hirschberg：对中行分别正反 DP，找分割点使两侧距离和最小，递归。</p><p>缺口是空间，不是新的编辑操作。</p><h3 id="不是近似匹配通配符课" tabindex="-1">不是近似匹配通配符课 <a class="header-anchor" href="#不是近似匹配通配符课" aria-label="Permalink to &quot;不是近似匹配通配符课&quot;">​</a></h3><p>通配、仿射缺口罚分（Gotoh）后课点名。本课单位代价 Levenshtein。不要把 KMP 当编辑距离。</p><p><span class="marginnote">Levenshtein 1966。Hirschberg 1975 原为 LCS，编辑距离同构。后课 Myers 位并行、\\(O(nd)\\) 差分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写标准 DP。只要长度用滚动。要路径用 Hirschberg 或存前驱。对角线优先可提前停（阈值）。</p>',11)),(a(),o(d,null,{default:i(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GR%5B%22n%C3%97m%20%E6%A0%BC%E5%9B%BE%22%5D%20--%3E%20DP%5B%22%E6%8F%92%E5%88%A0%E6%94%B9%E6%9C%80%E7%9F%AD%E8%B7%AF%22%5D%0A%20%20DP%20--%3E%20HB%5B%22%E4%B8%AD%E7%BA%BF%E5%88%86%E6%B2%BB%E8%BF%98%E5%8E%9F%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>边界：空串对长度为对方长度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>格图 DAG，边权 0/1，DP 即 DAG 最短路。Hirschberg：最优路径必过中线某点，该点最小化左半+右半。与分治优化不同：这里分治的是路径空间不是决策单调。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 DNA 仿射缺口全文。不写块编辑。后课默认：编辑距离 \\(O(nm)\\)；线性空间还原用 Hirschberg。下一课比对与位并行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编辑距离 = 格图最短路 \\(O(nm)\\)。</li><li>Hirschberg 线性空间还原路径。</li><li>与 LCS 同一张格，代价不同。</li><li>出处：Levenshtein, 1966；Hirschberg, 1975。</li></ul>',7))])}const P=s(p,[["render",m]]);export{A as __pageData,P as default};
